public static class Files {
    public static readonly string Root=Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);
    public static readonly string Engine=Path.Combine(Root,"Saves");
    public static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=16000000};
    public static void Atomic(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".tmp";File.WriteAllText(temp,text,new UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
    public static void Log(string text){try{Directory.CreateDirectory(Engine);File.AppendAllText(Path.Combine(Engine,"launcher.log"),DateTime.Now.ToString("s")+" "+text+Environment.NewLine,Encoding.UTF8);}catch{}}
    public static void Open(string path){Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}
}
public sealed class Preferences {
    public string Language="tr",GameLanguage="en";
    public bool Fullscreen=true,Vsync=true,Crisp=false,HqAudio=true,Vibration=true,AutoPause=true,SkipIntro=false,DiscordPresence=true,DiscordRoom=true,DirectPlay=false;
    public int Fill=1,Scale=3,FpsLimit=120,Music=80,Effects=100,Aim=100,Deadzone=18,PadSpeed=1;
    public Dictionary<string,string> Keys=new Dictionary<string,string>{{"press","Return"},{"pause","Escape"},{"zoom_in","E"},{"zoom_out","Q"},{"shake","F"},{"fullscreen","F11"},{"screenshot","F12"},{"cover","Space"},{"aim_up","W"},{"aim_down","S"},{"aim_left","A"},{"aim_right","D"}};
    public Dictionary<string,int> Pad=new Dictionary<string,int>{{"press",0},{"pause",6},{"back",1},{"zoom_in",10},{"zoom_out",9},{"shake",3},{"cover",7}};
    public static Preferences Load(){try{var p=Files.Json.Deserialize<Preferences>(File.ReadAllText(Path.Combine(Files.Root,"settings.json"),Encoding.UTF8));p.Normalize();return p;}catch{return new Preferences();}}
    private void Normalize(){var d=new Preferences();Language=TouchLanguagePacks.Normalize(Language);GameLanguage=TouchLanguagePacks.ResolveGame(GameLanguage);if(Keys==null)Keys=d.Keys;if(Pad==null)Pad=d.Pad;foreach(var x in d.Keys)if(!Keys.ContainsKey(x.Key))Keys[x.Key]=x.Value;foreach(var x in d.Pad)if(!Pad.ContainsKey(x.Key))Pad[x.Key]=x.Value;}
    public void Save(){Normalize();Directory.CreateDirectory(Files.Engine);Files.Atomic(Path.Combine(Files.Root,"settings.json"),Files.Json.Serialize(this));var b=new StringBuilder();Action<string,object> add=(k,v)=>b.AppendLine(k+"="+Convert.ToString(v,CultureInfo.InvariantCulture));
        add("language",GameLanguage);add("fullscreen",Fullscreen?1:0);add("vsync",Vsync?1:0);add("max_fps",FpsLimit);add("fill",Fill);add("render_scale",Scale);add("deadzone",Deadzone/100.0);foreach(var x in Keys)add("key_"+x.Key,x.Value);foreach(var x in Pad)add("pad_"+x.Key,x.Value);Files.Atomic(Path.Combine(Files.Root,"Oyun","desktop.ini"),b.ToString());
        b.Clear();add("sharp_rendering",0);add("screen_fill",Fill);add("crisp_pixels",Crisp?1:0);add("music_volume",Music);add("effects_volume",Effects);add("hq_resampling",HqAudio?1:0);add("vibration",Vibration?1:0);add("aim_sensitivity",Aim);add("touch_tolerance",3);add("controller_speed",PadSpeed);add("language",0);add("skip_intro",SkipIntro?1:0);add("pause_button",1);add("pause_on_leave",AutoPause?1:0);Files.Atomic(Path.Combine(Files.Engine,"retouched.cfg"),b.ToString());
    }
}
public static class Loc {
    public static string Language="tr";
    public static string Normalize(string s){return TouchLanguagePacks.Normalize(s);}
    public static string T(string s){return TouchLocale.Translate(s,Language);}
    public static string For(string s,string lang){return TouchLocale.Translate(s,lang);}
    public static string L(string tr,string en){return Language=="tr"?tr:TouchLanguagePacks.Translate(en,Language);}
    public static string E(string en){return TouchLanguagePacks.Translate(en,Language);}
}
public static class TranslationImport {
    static void Be(Stream s,ulong n,int width){for(int i=width-1;i>=0;i--)s.WriteByte((byte)(n>>(i*8)));}
    static void Length(Stream s,int marker,int n){if(n<15)s.WriteByte((byte)(marker|n));else{s.WriteByte((byte)(marker|15));int width=n<256?1:n<65536?2:4;s.WriteByte((byte)(0x10+(width==1?0:width==2?1:2)));Be(s,(ulong)n,width);}}
    public static byte[] Plist(IList<KeyValuePair<string,string>> values){int count=1+values.Count*2,refSize=count<256?1:2;var objects=new List<byte[]>();using(var s=new MemoryStream()){Length(s,0xd0,values.Count);for(int i=0;i<values.Count;i++)Be(s,(ulong)(i*2+1),refSize);for(int i=0;i<values.Count;i++)Be(s,(ulong)(i*2+2),refSize);objects.Add(s.ToArray());}foreach(var pair in values)foreach(string text in new[]{pair.Key,pair.Value})using(var s=new MemoryStream()){bool ascii=text.All(c=>c<128);Length(s,ascii?0x50:0x60,text.Length);byte[] bytes=(ascii?Encoding.ASCII:Encoding.BigEndianUnicode).GetBytes(text);s.Write(bytes,0,bytes.Length);objects.Add(s.ToArray());}using(var s=new MemoryStream()){byte[] header=Encoding.ASCII.GetBytes("bplist00");s.Write(header,0,header.Length);var offsets=new List<ulong>();foreach(byte[] obj in objects){offsets.Add((ulong)s.Position);s.Write(obj,0,obj.Length);}ulong table=(ulong)s.Position;foreach(ulong offset in offsets)Be(s,offset,4);s.Write(new byte[6],0,6);s.WriteByte(4);s.WriteByte((byte)refSize);Be(s,(ulong)count,8);Be(s,0,8);Be(s,table,8);return s.ToArray();}}
    static Dictionary<string,object> Document(string path){var d=Files.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(path,Encoding.UTF8));if(Convert.ToString(d["format"])!="patriots.mgs-touch.localization.v1")throw new InvalidDataException("MGS Touch localization.v1 JSON required");return d;}
    static List<Dictionary<string,object>> Rows(object data){return ((System.Collections.IEnumerable)data).Cast<object>().Select(x=>(Dictionary<string,object>)x).ToList();}
    public static int Import(string path){var d=Document(path);var original=Document(Path.Combine(Files.Root,"Localization","metal_gear_solid_touch_english.json"));if(Convert.ToString(d["source_sha256"])!=Convert.ToString(original["source_sha256"]))throw new InvalidDataException("Source version mismatch");var rows=Rows(d["entries"]);var source=Rows(original["entries"]).ToDictionary(x=>Convert.ToString(x["id"]));if(rows.Count!=source.Count)throw new InvalidDataException("Missing localization records");var seen=new HashSet<string>();var pairs=new List<KeyValuePair<string,string>>();int changed=0;foreach(var row in rows){string id=Convert.ToString(row["id"]);if(!seen.Add(id)||!source.ContainsKey(id))throw new InvalidDataException("Duplicate or unknown ID: "+id);var reference=source[id];string text=Convert.ToString(row["text"]);if(Convert.ToString(row["source"])!=Convert.ToString(reference["source"]))throw new InvalidDataException("Original source changed: "+id);if(Convert.ToString(reference["kind"])=="font"&&text!=Convert.ToString(reference["text"]))throw new InvalidDataException("Font changed: "+id);if(text.IndexOf('\0')>=0)throw new InvalidDataException("NUL text: "+id);if(text!=Convert.ToString(reference["source"]))changed++;pairs.Add(new KeyValuePair<string,string>(id,text));}
        string folder=Path.Combine(Files.Root,"Oyun","languages","tr","Turkish.lproj");Directory.CreateDirectory(folder);string dest=Path.Combine(folder,"Localizable.strings");if(File.Exists(dest))File.Copy(dest,dest+".previous",true);File.WriteAllBytes(dest,Plist(pairs));File.Copy(path,Path.Combine(Files.Root,"Localization","installed_turkish.json"),true);
        // Constant overrides are passed through a compact, length-prefixed UTF-8 table.
        var constants=Rows(d["constants"]).Where(r=>Convert.ToBoolean(r["translatable"])&&Convert.ToString(r["text"])!=Convert.ToString(r["source"])).ToList();using(var s=File.Create(Path.Combine(Files.Root,"Oyun","languages","tr","runtime_text.bin"))){var magic=Encoding.ASCII.GetBytes("PTXT0001");s.Write(magic,0,8);Be(s,(ulong)constants.Count,4);foreach(var r in constants)foreach(string key in new[]{"source","text"}){byte[] bytes=Encoding.UTF8.GetBytes(Convert.ToString(r[key]));Be(s,(ulong)bytes.Length,4);s.Write(bytes,0,bytes.Length);}}
        Files.Atomic(Path.Combine(Files.Root,"Localization","translation_status.json"),Files.Json.Serialize(new{changed=changed,total=445,constants=constants.Count,imported=DateTime.UtcNow.ToString("o")}));return changed;
    }
}
