    void Saves(){Heading("07 / PROGRESS",L("Kayıt yönetimi","Save management"),L("Kayıtlar paketin Saves klasöründe tutulur.","Progress is stored in the package’s Saves folder."));string file=Path.Combine(Files.Engine,"SAVE.data");Note(File.Exists(file)?L("Son kayıt: ","Last save: ")+File.GetLastWriteTime(file).ToString("g"):L("Henüz bir oyun kaydı yok.","No save file yet."));var b=new StackPanel{Orientation=Orientation.Horizontal};b.Children.Add(Button(L("KAYIT KLASÖRÜ","SAVE FOLDER"),()=>{Directory.CreateDirectory(Files.Engine);Files.Open(Files.Engine);}));b.Children.Add(Button(L("YEDEK AL","BACK UP"),()=>{EnsureStopped();if(!File.Exists(file))throw new FileNotFoundException(L("Kayıt bulunamadı.","No save found."));string dest=Path.Combine(Files.Engine,"Backups");Directory.CreateDirectory(dest);File.Copy(file,Path.Combine(dest,"SAVE-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".data"));status.Text=L("Yedek oluşturuldu.","Backup created.");}));b.Children.Add(Button(L("YEDEK YÜKLE","RESTORE BACKUP"),()=>{EnsureStopped();var d=new OpenFileDialog{Filter="MGS Touch save|*.data"};if(d.ShowDialog(this)!=true)return;byte[] bytes=File.ReadAllBytes(d.FileName);if(bytes.Length!=1024)throw new InvalidDataException(L("Kayıt 1024 bayt olmalı.","The save must be 1024 bytes."));if(File.Exists(file))File.Copy(file,file+".before-restore",true);File.WriteAllBytes(file,bytes);Build();}));body.Children.Add(b);}
    void About(){Heading("08 / CREDITS",L("Proje hakkında","About the project"),"METAL GEAR SOLID TOUCH · PATRIOTS PC");Note(L("Windows çalıştırıcısı, yerel olarak çözümlenen oyun kodunun wasm32 → C dönüşümüyle derlenir. Orijinal oyun: Konami / Kojima Productions. Tersine mühendislik ve platform temeli: etruj / mgs-retouched. PC uyarlaması ve çeviri araçları: Patriots.","The Windows host compiles locally recovered game code through wasm32 → C. Original game: Konami / Kojima Productions. Reverse engineering and platform foundation: etruj / mgs-retouched. PC integration and localization tools: Patriots."));body.Children.Add(Button(L("LİSANSLAR VE BİLGİLER","LICENSES AND INFORMATION"),()=>Files.Open(Path.Combine(Files.Root,"Licenses"))));}
    async void StartGame(){
        bool test=args.Contains("--test-lifecycle");
        try{
            if(game!=null&&!game.HasExited){ShowWindow(game.MainWindowHandle,9);SetForegroundWindow(game.MainWindowHandle);return;}
            string exe=Path.Combine(Files.Root,"Oyun","mgs_touch.exe");
            if(!File.Exists(exe))throw new FileNotFoundException(L("Oyun çalıştırıcısı bulunamadı.","The game executable is missing."),exe);
            settings.GameLanguage=TouchLanguagePacks.ResolveGame(settings.GameLanguage);
            settings.Save();
            var start=new ProcessStartInfo(exe){WorkingDirectory=Path.GetDirectoryName(exe),UseShellExecute=false,CreateNoWindow=true};
            if(test){string qa=Path.Combine(Files.Root,"QA","LifecycleSaves");Directory.CreateDirectory(qa);start.Arguments="--windowed --test-seconds 9 --save-dir \""+qa+"\"";}
            game=Process.Start(start);
            discord=new DiscordPresence(game.Id,settings.GameLanguage);
            // Keep only the background Discord session alive while playing.
            // The launcher window and its taskbar button return after game exit.
            ShowInTaskbar=false;Hide();
            var current=game;
            Task<bool> check=test?VerifyHiddenSession(current):null;
            await Task.Run(()=>current.WaitForExit());
            int code=current.ExitCode;
            bool verified=check==null||await check;
            if(discord!=null){discord.Dispose();discord=null;}
            game=null;ShowInTaskbar=true;Show();Activate();Build();
            status.Text=code==0?L("Oyun kapandı.","Game closed."):L("Oyun hata verdi. Saves/runtime.log kaydını incele.","The game reported an error. See Saves/runtime.log.");
            if(test){if(!verified||!IsVisible||!ShowInTaskbar||code!=0)throw new Exception("Launcher lifecycle test failed");File.WriteAllText(Path.Combine(Files.Root,"QA","launcher_lifecycle_test.json"),"{\"passed\":true,\"hidden_during_game\":true,\"second_launch_stays_hidden\":true,\"restored_after_game\":true,\"native_window_icons\":true}");Close();}
        }catch(Exception e){
            Files.Log(e.ToString());
            if(test){Application.Current.Shutdown(1);return;}
            ShowInTaskbar=true;Show();MessageBox.Show(this,e.Message,"MGS Touch",MessageBoxButton.OK,MessageBoxImage.Error);
        }
    }
    async Task<bool> VerifyHiddenSession(Process current){
        await Task.Delay(2200);
        current.Refresh();
        bool ok=!IsVisible&&!ShowInTaskbar&&Icon!=null&&current.MainWindowHandle!=IntPtr.Zero;
        ok=ok&&SendMessage(current.MainWindowHandle,0x007F,new IntPtr(1),IntPtr.Zero)!=IntPtr.Zero&&SendMessage(current.MainWindowHandle,0x007F,IntPtr.Zero,IntPtr.Zero)!=IntPtr.Zero;
        using(var second=Process.Start(new ProcessStartInfo(Assembly.GetExecutingAssembly().Location,"--settings"){UseShellExecute=false,CreateNoWindow=true})){await Task.Run(()=>second.WaitForExit());ok=ok&&second.ExitCode==0;}
        await Task.Delay(250);
        return ok&&!IsVisible&&!ShowInTaskbar;
    }
