    [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr h);
    [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool ShowWindow(IntPtr h,int n);
    void RenderAll(){string folder=Path.Combine(Files.Root,"QA");Directory.CreateDirectory(folder);foreach(string lang in new[]{"tr","en"}.Concat(TouchLanguagePacks.Available().Where(l=>l.id!="tr"&&l.id!="en").Select(l=>l.id))){settings.Language=lang;Loc.Language=lang;foreach(string page in new[]{"home","display","controls","translation","discord"}){active=page;Build();UpdateLayout();var b=new RenderTargetBitmap((int)ActualWidth,(int)ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(b));using(var stream=File.Create(Path.Combine(folder,"launcher-"+lang+"-"+page+".png")))encoder.Save(stream);}}Close();}
